+/** Chooses `ko` or `en` from an Accept-Language header, falling back to `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const defaultLang = LANGUAGES.includes(fallback) ? fallback : LANGUAGES[0];
+  if (typeof header !== "string" || !header.trim()) return defaultLang;
+  const candidates = [];
+  header.split(",").forEach((part, index) => {
+    const [rawTag, ...params] = part.trim().split(";");
+    if (!rawTag) return;
+    const lang = rawTag.trim().split(/[-_]/)[0].toLowerCase();
+    if (!LANGUAGES.includes(lang)) return;
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p.trim());
+      if (m) q = Number(m[1]);
+    }
+    if (!Number.isFinite(q) || q <= 0 || q > 1) return;
+    candidates.push({ lang, q, index });
+  });
+  if (!candidates.length) return defaultLang;
+  candidates.sort((a, b) => b.q - a.q || a.index - b.index);
+  return candidates[0].lang;
+}
